// pp:data-source live

// mailboxRecord is a single mailbox flattened out of the domain-grouped
// /v2/mailboxes/list response, tagged with its parent domain.
type mailboxRecord struct {
	ID         string `json:"id"`
	Email      string `json:"email"`
	Status     string `json:"status"`
	IsWarmedUp bool   `json:"isWarmedUp"`
	Domain     string `json:"domain"`
}

// mailboxListEnvelope models the data payload of /v2/mailboxes/list.
type mailboxListEnvelope struct {
	Data struct {
		CurrentPage        int `json:"currentPage"`
		TotalPages         int `json:"totalPages"`
		AvailableMailboxes int `json:"availableMailboxes"`
		Domains            []struct {
			ID        string `json:"id"`
			Domain    string `json:"domain"`
			Mailboxes []struct {
				ID         string `json:"id"`
				Email      string `json:"email"`
				Status     string `json:"status"`
				IsWarmedUp bool   `json:"isWarmedUp"`
			} `json:"mailboxes"`
		} `json:"domains"`
	} `json:"data"`
}

// fetchAllMailboxes pages through /v2/mailboxes/list and returns every mailbox
// flattened with its domain, plus the available-mailbox count (paid capacity
// not yet provisioned) reported on the first page.
func fetchAllMailboxes(cmd *cobra.Command, flags *rootFlags) ([]mailboxRecord, int, error) {
	c, err := flags.newClient()
	if err != nil {
		return nil, 0, err
	}
	var all []mailboxRecord
	available := 0
	page := 1
	const maxPages = 100
	for page <= maxPages {
		params := map[string]string{"page": fmt.Sprintf("%d", page), "limit": "100"}
		raw, err := c.Get(cmd.Context(), "/v2/mailboxes/list", params)
		if err != nil {
			return nil, 0, classifyAPIError(err, flags)
		}
		var env mailboxListEnvelope
		if err := json.Unmarshal(raw, &env); err != nil {
			return nil, 0, fmt.Errorf("parsing mailbox list: %w", err)
		}
		if page == 1 {
			available = env.Data.AvailableMailboxes
		}
		for _, d := range env.Data.Domains {
			for _, m := range d.Mailboxes {
				all = append(all, mailboxRecord{
					ID:         m.ID,
					Email:      m.Email,
					Status:     m.Status,
					IsWarmedUp: m.IsWarmedUp,
					Domain:     d.Domain,
				})
			}
		}
		if env.Data.TotalPages <= page || env.Data.TotalPages == 0 {
			break
		}
		page++
	}
	return all, available, nil
}

type idleResult struct {
	WarmedMailboxes      []mailboxRecord `json:"warmedMailboxes"`
	WarmedCount          int             `json:"warmedCount"`
	AvailableMailboxes   int             `json:"availableMailboxes"`
	UnprovisionedMessage string          `json:"note,omitempty"`
}

func newNovelMailboxesIdleCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "idle",
		Short: "Warmed mailboxes ready to send plus paid-but-unprovisioned capacity",
		Long: strings.Trim(`
List warmed-up mailboxes (your ready-to-send inventory) and report how many paid
mailboxes you have not yet provisioned onto a domain. Use this to recover send
capacity you are paying for but not using.

Do NOT use this to list failed creations; use 'mailboxes failed'. For every
mailbox regardless of state, use 'mailboxes list'.
`, "\n"),
		Example:     "  zapmail-pp-cli mailboxes idle --json",
		Annotations: map[string]string{"mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if dryRunOK(flags) {
				return nil
			}
			all, available, err := fetchAllMailboxes(cmd, flags)
			if err != nil {
				return err
			}
			warmed := []mailboxRecord{}
			for _, m := range all {
				if m.IsWarmedUp {
					warmed = append(warmed, m)
				}
			}
			res := idleResult{
				WarmedMailboxes:    warmed,
				WarmedCount:        len(warmed),
				AvailableMailboxes: available,
			}
			if available > 0 {
				res.UnprovisionedMessage = fmt.Sprintf("%d purchased mailboxes are not yet assigned to a domain", available)
			}
			fmt.Fprintf(cmd.ErrOrStderr(), "idle: %d warmed mailboxes, %d paid-but-unprovisioned\n", len(warmed), available)
			return printJSONFiltered(cmd.OutOrStdout(), res, flags)
		},
	}
	return cmd
}
